import requests
import json
import time
import random
import string

class TikTokAccount:
    def __init__(self, username, password):
        self.username = username
        self.password = password
        self.session = requests.Session()

    def login(self):
        data = {
            'username': self.username,
            'password': self.password
        }
        response = self.session.post('https://www.tiktok.com/node/user/login', data=data)
        return response.json()

    def get_videos(self):
        response = self.session.get('https://www.tiktok.com/api/item/list/')
        return response.json()

def create_account(username, password):
    account = TikTokAccount(username, password)
    account.login()
    return account

def scrape_videos(account):
    videos = account.get_videos()
    for video in videos['item_list']['items']:
        print(video['video']['play_addr']['url_list'][0])

def main():
    usernames = ['account1', 'account2', 'account3']
    passwords = ['password1', 'password2', 'password3']

    for i in range(len(usernames)):
        account = create_account(usernames[i], passwords[i])
        scrape_videos(account)
        time.sleep(random.randint(1, 5))

if __name__ == '__main__':
    main()
